// Offline cache for the installed web app. The precache list is generated by tools/export_web.py
// (sw-manifest.json) so every data file, model, doc and vendor file is available offline.
// Strategy: network first for data and docs (so updates arrive), cache first for everything else.
const VERSION = 'skyforge-v18-1acaf80b34';
self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const list = await (await fetch('sw-manifest.json', { cache: 'no-store' })).json();
    const cache = await caches.open(VERSION);
    await cache.addAll(list);
    await self.skipWaiting();
  })());
});
self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k !== VERSION) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET' || url.origin !== location.origin) return;
  const fresh = url.pathname.includes('/data/') || url.pathname.includes('/docs/');
  e.respondWith((async () => {
    const cache = await caches.open(VERSION);
    if (fresh) {
      try {
        const r = await fetch(e.request);
        if (r.ok) cache.put(e.request, r.clone());
        return r;
      } catch {
        return (await cache.match(e.request)) || Response.error();
      }
    }
    return (await cache.match(e.request, { ignoreSearch: true })) || fetch(e.request);
  })());
});
